-- SOS Barnbyar demo: content for the 'Test lektion' package (barnbyar-1..5).
-- Five short lessons (~6 min each, 3 steps + 4 quiz questions) for the 30-minute
-- quiz part of a one-hour session. Target group 16–25, Swedish only.
-- Facts checked against csn.se and forsakringskassan.se in November 2026.

update public.lessons set title = 'Pengar och din första budget', description = 'Behov och önskemål, vart pengarna tar vägen och hur du gör en enkel budget.', estimated_minutes = 6, xp_reward = 50, content = '{"steps": [{"label": "Steg 1 av 3 – Behov eller önskemål?", "title": "Behov eller önskemål?", "body": "<p>Pengar räcker sällan till allt på en gång. Därför handlar privatekonomi om att <strong>välja</strong>.</p><p>Ett <strong>behov</strong> är något du måste ha: mat, ett ställe att bo, kläder efter väder, mobil och resor till skolan eller jobbet.</p><p>Ett <strong>önskemål</strong> är något som är kul att ha men som du klarar dig utan: nya sneakers fast de gamla funkar, take away, ännu en streamingtjänst.</p><div class=\"modal-callout\">Önskemål är inte fel. Poängen är att behoven betalas först.</div>"}, {"label": "Steg 2 av 3 – Vart tar pengarna vägen?", "title": "Vart tar pengarna vägen?", "body": "<p>Små köp varje dag märks knappt, men de blir mycket tillsammans.</p><div class=\"modal-example\"><div class=\"modal-example-label\">Räkneexempel</div><p>En energidryck för 25 kr fem dagar i veckan<br>= 125 kr i veckan<br>= ungefär <strong>6 500 kr per år</strong></p></div><p>Testa att skriva upp allt du köper under en vecka. De flesta blir förvånade.</p><details class=\"deep\"><summary>Fördjupning: fasta och rörliga utgifter</summary><p><strong>Fasta utgifter</strong> är ungefär lika stora varje månad, till exempel hyra, mobilabonnemang och försäkring. <strong>Rörliga utgifter</strong> ändras, till exempel mat, kläder och nöjen.</p><p>Det är oftast de rörliga utgifterna som är lättast att dra ner på när pengarna inte räcker.</p></details>"}, {"label": "Steg 3 av 3 – Gör en enkel budget", "title": "Gör en enkel budget", "body": "<p>En <strong>budget</strong> är en plan för pengarna. Du skriver upp vad som kommer in (inkomster) och vad som går ut (utgifter) under en månad.</p><div class=\"modal-example\"><div class=\"modal-example-label\">Exempel: Amira, 19 år</div><p>In: 9 000 kr<br>Hyra: 4 500 kr · Mat: 2 500 kr · Mobil: 200 kr · Busskort: 600 kr · Nöjen: 700 kr<br>Kvar: <strong>500 kr</strong>, som hon sparar</p></div><div class=\"modal-callout\">Inkomster minus utgifter ska bli noll eller mer. Blir det minus behöver du ändra något.</div><details class=\"deep\"><summary>Fördjupning: budgetregeln 50/30/20</summary><p>En vanlig tumregel: ungefär 50 % till behov, 30 % till önskemål och 20 % till sparande. När man har små marginaler går det sällan att följa exakt, och det är okej. Det viktiga är att du vet vart pengarna går.</p><p>Konsumentverket har siffror på vad mat och andra vardagskostnader brukar kosta, som du kan använda när du gör din budget.</p></details>"}], "quiz": [{"question": "Vilket av de här är ett behov?", "options": ["En ny mobil fast den gamla fungerar", "Mat för veckan", "En biobiljett", "Ett nytt spel"], "correct_index": 1, "feedback": "Rätt – mat måste du ha för att klara vardagen."}, {"question": "Vad är en budget?", "options": ["Ett sparkonto på banken", "En plan för vad som kommer in och går ut", "En sorts lån", "En räkning från staten"], "correct_index": 1, "feedback": "Rätt – en budget är en plan för dina pengar."}, {"question": "Du köper en energidryck för 25 kr fem dagar i veckan. Ungefär hur mycket blir det på ett år?", "options": ["600 kr", "1 300 kr", "6 500 kr", "25 000 kr"], "correct_index": 2, "feedback": "Rätt – 125 kr i veckan blir ungefär 6 500 kr på ett år."}, {"question": "Budgeten visar minus. Vad är ett bra första steg?", "options": ["Ta ett snabblån", "Strunta i det", "Se över de rörliga utgifterna, till exempel nöjen och take away", "Sluta betala hyran"], "correct_index": 2, "feedback": "Rätt – de rörliga utgifterna är oftast lättast att ändra."}]}'::jsonb where id = 'barnbyar-1';
update public.lessons set title = 'Inkomster och rätten till stöd', description = 'Lön och skatt, CSN, bostadsbidrag och försörjningsstöd – vilka pengar du kan ha rätt till.', estimated_minutes = 6, xp_reward = 50, content = '{"steps": [{"label": "Steg 1 av 3 – Lön och skatt", "title": "Lön och skatt", "body": "<p>När du jobbar får du <strong>lön</strong>. Innan pengarna kommer till dig dras <strong>skatt</strong>. Skatten betalar till exempel skola, vård och busstrafik.</p><p>Lönen före skatt heter <strong>bruttolön</strong>. Det du faktiskt får på kontot heter <strong>nettolön</strong>.</p><div class=\"modal-example\"><div class=\"modal-example-label\">Räkneexempel</div><p>Bruttolön: 25 000 kr i månaden<br>Nettolön: ungefär <strong>20 000 kr</strong> (beror på vilken kommun du bor i)</p></div><details class=\"deep\"><summary>Fördjupning: lönebesked och deklaration</summary><p>På ditt <strong>lönebesked</strong> ser du bruttolön, skatt och nettolön. Kolla alltid att timmarna stämmer.</p><p>Tjänar du lite under ett helt år, ungefär under 25 000 kr, blir det ingen skatt alls. Har arbetsgivaren ändå dragit skatt får du tillbaka den när du deklarerat. Deklarationen gör du hos Skatteverket varje vår, oftast med BankID i appen.</p></details>"}, {"label": "Steg 2 av 3 – CSN – pengar när du studerar", "title": "CSN – pengar när du studerar", "body": "<p>Går du på <strong>gymnasiet</strong> får du <strong>studiebidrag</strong> från CSN: <strong>1 250 kr i månaden</strong>. Du behöver inte söka, det kommer automatiskt. Är du under 18 betalas det till din vårdnadshavare, från 18 år till ditt eget konto.</p><p>Studerar du på <strong>komvux, folkhögskola eller högskola</strong> kan du söka <strong>studiemedel</strong>. Det består av ett bidrag och ett lån, och lånet betalar du tillbaka senare.</p><div class=\"modal-callout\">Studiebidraget på gymnasiet behöver du aldrig betala tillbaka.</div><details class=\"deep\"><summary>Fördjupning: extra tillägg och studiemedel</summary><p>Har din familj låg inkomst, under 125 000 kr före skatt per läsår, kan du söka <strong>extra tillägg</strong>. Det kommer inte automatiskt, så du måste söka varje läsår.</p><p>Fullt studiemedel för heltidsstudier är 2026 ungefär 13 600 kr per fyra veckor, bidrag och lån tillsammans. Studiemedel kan du tidigast få från andra halvåret det år du fyller 20. Tjänar du för mycket vid sidan av (fribeloppet) kan du få betala tillbaka.</p></details>"}, {"label": "Steg 3 av 3 – Bostadsbidrag och försörjningsstöd", "title": "Bostadsbidrag och försörjningsstöd", "body": "<p><strong>Bostadsbidrag</strong> söker du hos <strong>Försäkringskassan</strong>. Är du under 29 år, har låg inkomst och betalar för ditt boende kan du få upp till <strong>1 300 kr i månaden</strong>. Du söker på Mina sidor, och bidraget gäller bara från månaden du söker.</p><p><strong>Försörjningsstöd</strong> (ekonomiskt bistånd) söker du hos <strong>socialtjänsten</strong> i din kommun. Det är till för när du inte kan få pengar till det du behöver på något annat sätt, till exempel genom lön, CSN eller andra bidrag.</p><div class=\"modal-callout\">Bidrag är en rättighet om du uppfyller kraven. Det är inget att skämmas över att söka.</div><details class=\"deep\"><summary>Fördjupning: berätta när något ändras</summary><p>Får du bostadsbidrag måste du direkt berätta för Försäkringskassan om din inkomst ändras eller om du flyttar. Året efter kontrollerar de din inkomst mot Skatteverket. Har du tjänat mer än du sa kan du behöva betala tillbaka.</p><p>Bor du som inneboende kan du inte få bostadsbidrag som ung. Får du eftervård eller stöd från socialtjänsten kan reglerna se olika ut, så fråga gärna din kontaktperson.</p></details>"}], "quiz": [{"question": "Vad är nettolön?", "options": ["Lönen före skatt", "Det du får på kontot efter skatt", "Skatten du betalar", "Din semesterersättning"], "correct_index": 1, "feedback": "Rätt – nettolön är lönen efter att skatten dragits."}, {"question": "Hur mycket studiebidrag får du per månad när du går på gymnasiet?", "options": ["500 kr", "1 250 kr", "3 000 kr", "Inget alls"], "correct_index": 1, "feedback": "Rätt – studiebidraget är 1 250 kr i månaden och kommer automatiskt."}, {"question": "Var söker du bostadsbidrag?", "options": ["Hos Skatteverket", "Hos banken", "Hos Försäkringskassan", "Hos hyresvärden"], "correct_index": 2, "feedback": "Rätt – bostadsbidrag söker du hos Försäkringskassan, på Mina sidor."}, {"question": "Du får bostadsbidrag och får ett nytt jobb med högre lön. Vad ska du göra?", "options": ["Ingenting", "Berätta det för Försäkringskassan direkt", "Vänta tills året är slut", "Säga upp lägenheten"], "correct_index": 1, "feedback": "Rätt – annars kan du behöva betala tillbaka pengar senare."}]}'::jsonb where id = 'barnbyar-2';
update public.lessons set title = 'Att bo själv', description = 'Hyreskontrakt, vad ett eget boende kostar och hur du undviker bostadsbedrägerier.', estimated_minutes = 6, xp_reward = 50, content = '{"steps": [{"label": "Steg 1 av 3 – Hitta en bostad", "title": "Hitta en bostad", "body": "<p>Ställ dig i <strong>bostadskö</strong> så tidigt du kan. Många kommuner har en kö, och ofta får du ställa dig från 18 år. Tiden i kön är det som räknas.</p><p>Ett <strong>förstahandskontrakt</strong> har du direkt med hyresvärden. Ett <strong>andrahandskontrakt</strong> har du med någon som själv hyr lägenheten. Det är ofta enklare att få, men tryggheten är sämre.</p><div class=\"modal-callout\">Skriv alltid ett skriftligt kontrakt, även när du hyr i andra hand.</div>"}, {"label": "Steg 2 av 3 – Vad kostar det att bo?", "title": "Vad kostar det att bo?", "body": "<p>Hyran är den största kostnaden, men den är inte den enda.</p><div class=\"modal-example\"><div class=\"modal-example-label\">Exempel på en månad</div><p>Hyra: 5 500 kr<br>El (om den inte ingår): 300 kr<br>Hemförsäkring: 150 kr<br>Internet: 300 kr<br>Mat: 2 500 kr<br>Totalt: <strong>8 750 kr</strong></p></div><p>En <strong>hemförsäkring</strong> skyddar dina saker vid till exempel brand, inbrott eller vattenskada. Den kostar ofta runt 100–200 kr i månaden för en ung person.</p><details class=\"deep\"><summary>Fördjupning: räkningar och autogiro</summary><p>Hyran betalas oftast i förskott, alltså före månaden du bor. Med <strong>autogiro</strong> eller e-faktura dras räkningarna automatiskt, så du missar inga betalningar.</p><p>Har du en ny lägenhet behöver du själv teckna elavtal om elen inte ingår. Annars får du ett dyrare anvisat avtal.</p></details>"}, {"label": "Steg 3 av 3 – Se upp för bostadsbedrägerier", "title": "Se upp för bostadsbedrägerier", "body": "<p>Det finns falska annonser för lägenheter. Bedragaren ber dig betala hyra eller <strong>deposition</strong> i förväg, och sen finns ingen lägenhet.</p><div class=\"modal-example\"><div class=\"modal-example-label\">Varningssignaler</div><p>Hyran är mycket lägre än för andra lägenheter<br>Du får inte titta på lägenheten<br>”Hyresvärden” är utomlands och vill ha pengar först</p></div><div class=\"modal-callout\">Betala aldrig något innan du har sett lägenheten och har ett kontrakt.</div><details class=\"deep\"><summary>Fördjupning: bostadsbidrag när du bor själv</summary><p>Har du låg inkomst och är under 29 år kan du kanske få bostadsbidrag, som vi pratade om i lektion 2. Försäkringskassan räknar bara med upp till 60 kvadratmeter, så en mindre lägenhet ger oftast mer i bidrag i förhållande till ytan.</p></details>"}], "quiz": [{"question": "Varför är det bra att ställa sig i bostadskö tidigt?", "options": ["Det kostar ingenting att bo då", "Tiden i kön är det som räknas", "Man får gratis möbler", "Man slipper betala hyra"], "correct_index": 1, "feedback": "Rätt – ju längre du har stått i kön, desto större chans att få en lägenhet."}, {"question": "Vad skyddar en hemförsäkring?", "options": ["Dina saker vid till exempel brand eller inbrott", "Din lön", "Ditt busskort", "Ditt studiebidrag"], "correct_index": 0, "feedback": "Rätt – hemförsäkringen skyddar dina saker och dig hemma."}, {"question": "Vilken är en varningssignal i en lägenhetsannons?", "options": ["Du får titta på lägenheten innan", "Hyresvärden vill ha deposition innan du sett lägenheten", "Det finns ett skriftligt kontrakt", "Hyran är som för liknande lägenheter"], "correct_index": 1, "feedback": "Rätt – betala aldrig innan du sett lägenheten och fått ett kontrakt."}, {"question": "Vad är ett förstahandskontrakt?", "options": ["Ett kontrakt direkt med hyresvärden", "Ett kontrakt med en kompis", "Ett muntligt löfte", "Ett kontrakt för en vecka"], "correct_index": 0, "feedback": "Rätt – med ett förstahandskontrakt hyr du direkt av hyresvärden."}]}'::jsonb where id = 'barnbyar-3';
update public.lessons set title = 'Spara och betala säkert', description = 'Varför en buffert är viktig, hur du sparar små belopp och hur du skyddar dig mot bedragare.', estimated_minutes = 6, xp_reward = 50, content = '{"steps": [{"label": "Steg 1 av 3 – Varför spara?", "title": "Varför spara?", "body": "<p>En <strong>buffert</strong> är pengar du sparar för oväntade saker: en trasig mobil, en tandläkarräkning eller en månad med mindre inkomst.</p><p>Börja litet. Även 100 kr i månaden gör skillnad.</p><div class=\"modal-example\"><div class=\"modal-example-label\">Räkneexempel</div><p>200 kr i månaden i ett år<br>= <strong>2 400 kr</strong> att ta av när något händer</p></div><div class=\"modal-callout\">Spara direkt när pengarna kommer in, inte det som blir över i slutet av månaden.</div><details class=\"deep\"><summary>Fördjupning: var ska pengarna ligga?</summary><p>Bufferten ska ligga på ett <strong>sparkonto</strong> som är skilt från kontot du handlar med, men som du snabbt kommer åt. Sparar du för något längre fram, flera år, kan fonder vara ett alternativ. Då kan värdet gå både upp och ner.</p></details>"}, {"label": "Steg 2 av 3 – Så luras bedragare", "title": "Så luras bedragare", "body": "<p>Bedragare ringer, sms:ar eller skriver i sociala medier. De låtsas ofta vara banken, polisen, Postnord eller en kompis som behöver hjälp.</p><div class=\"modal-example\"><div class=\"modal-example-label\">Vanliga knep</div><p>”Ditt konto är hotat, logga in med BankID nu!”<br>”Ditt paket väntar, betala 19 kr här.”<br>”Vill du tjäna snabba pengar? Låna ut ditt konto.”</p></div><div class=\"modal-callout\">Banken och polisen ber dig aldrig att logga in eller signera med BankID när de ringer dig.</div>"}, {"label": "Steg 3 av 3 – Skydda dig", "title": "Skydda dig", "body": "<p>Ge aldrig ut dina koder och använd aldrig BankID för att någon annan ber dig om det.</p><p>Låna aldrig ut ditt konto eller din Swish till någon annan. Det kan vara <strong>penningtvätt</strong>, och då kan du själv bli ansvarig.</p><p>Har något hänt? <strong>Ring banken direkt</strong> och spärra, och anmäl sedan till polisen.</p><details class=\"deep\"><summary>Fördjupning: Swish och köp på nätet</summary><p>Swish är som att ge kontanter. Pengarna går oftast inte att få tillbaka. Swisha därför bara till personer du känner. Handlar du begagnat från en okänd, använd en tjänst med köpskydd eller mötas och betala när du ser varan.</p></details>"}], "quiz": [{"question": "Vad är en buffert?", "options": ["Ett lån", "Sparade pengar för oväntade utgifter", "En sorts aktie", "En räkning"], "correct_index": 1, "feedback": "Rätt – bufferten är dina pengar för när något oväntat händer."}, {"question": "När är det bäst att spara?", "options": ["Det som blir över i slutet av månaden", "Direkt när pengarna kommer in", "Bara när man fyller år", "Aldrig"], "correct_index": 1, "feedback": "Rätt – spara först så blir det av."}, {"question": "Någon ringer och säger att de är från banken. De vill att du loggar in med BankID. Vad gör du?", "options": ["Loggar in snabbt", "Lägger på och ringer banken själv", "Ger dem dina koder", "Skickar en Swish"], "correct_index": 1, "feedback": "Rätt – banken ber dig aldrig logga in när de ringer dig."}, {"question": "En okänd person vill låna ditt konto och betala dig för det. Vad gäller?", "options": ["Det är ett bra extrajobb", "Det kan vara penningtvätt och du kan bli ansvarig", "Det är helt lagligt", "Banken hjälper dig då"], "correct_index": 1, "feedback": "Rätt – låna aldrig ut ditt konto eller din Swish."}]}'::jsonb where id = 'barnbyar-4';
update public.lessons set title = 'Lån, skulder och var du får hjälp', description = 'Vad det kostar att låna, vad som händer om du inte betalar och var du får gratis hjälp.', estimated_minutes = 6, xp_reward = 50, content = '{"steps": [{"label": "Steg 1 av 3 – Vad kostar ett lån?", "title": "Vad kostar ett lån?", "body": "<p>Ett lån är pengar du får nu men måste betala tillbaka senare, med <strong>ränta</strong>. Räntan är priset för att låna. Ofta tillkommer också <strong>avgifter</strong>.</p><p>Den <strong>effektiva räntan</strong> visar vad lånet kostar totalt, med avgifterna inräknade.</p><div class=\"modal-example\"><div class=\"modal-example-label\">Köp nu, betala sen</div><p>Hörlurar för 2 000 kr på delbetalning<br>Med ränta och avgifter kan du till slut betala <strong>2 400 kr eller mer</strong></p></div><div class=\"modal-callout\">Jämför alltid den effektiva räntan. Snabblån och sms-lån är ofta mycket dyra.</div>"}, {"label": "Steg 2 av 3 – Om du inte kan betala", "title": "Om du inte kan betala", "body": "<p>Betalar du inte en räkning kommer först en <strong>påminnelse</strong>, sedan ett <strong>inkassokrav</strong>. Betalar du fortfarande inte kan skulden hamna hos <strong>Kronofogden</strong>.</p><p>Då kan du få en <strong>betalningsanmärkning</strong>. Den syns i tre år och gör det svårare att hyra lägenhet eller få ett mobilabonnemang.</p><div class=\"modal-callout\">Öppna alltid dina brev och din digitala brevlåda, även när det känns jobbigt.</div><details class=\"deep\"><summary>Fördjupning: varför avgifterna växer</summary><p>Varje steg lägger till avgifter: påminnelseavgift, inkassoavgift och sedan avgift hos Kronofogden. Dessutom fortsätter dröjsmålsräntan att växa. En räkning på några hundra kronor kan på det sättet bli flera gånger så stor.</p></details>"}, {"label": "Steg 3 av 3 – Här får du hjälp", "title": "Här får du hjälp", "body": "<p>Kan du inte betala? <strong>Hör av dig direkt</strong> till den du är skyldig och fråga om en <strong>betalningsplan</strong>. Det är mycket lättare innan skulden går vidare.</p><div class=\"modal-example\"><div class=\"modal-example-label\">Gratis hjälp</div><p><strong>Budget- och skuldrådgivning</strong> i din kommun<br><strong>Kronofogden</strong> – kolla om du har skulder och få råd<br>En vuxen du litar på, till exempel din kontaktperson</p></div><div class=\"modal-callout\">Det är aldrig för sent att be om hjälp, och ju tidigare desto bättre.</div><details class=\"deep\"><summary>Fördjupning: skuldsanering</summary><p>Har man så stora skulder att man aldrig kommer kunna betala dem kan man ansöka om <strong>skuldsanering</strong> hos Kronofogden. Man betalar då så mycket man kan under några år, och sedan stryks resten. Budget- och skuldrådgivningen kan hjälpa till med ansökan.</p></details>"}], "quiz": [{"question": "Vad är ränta?", "options": ["En avgift för att spara", "Priset för att låna pengar", "En sorts skatt", "Pengar från staten"], "correct_index": 1, "feedback": "Rätt – räntan är vad det kostar att låna."}, {"question": "Vad visar den effektiva räntan?", "options": ["Bara räntan utan avgifter", "Hela kostnaden för lånet, med avgifter", "Hur mycket du får låna", "Hur snabbt du får pengarna"], "correct_index": 1, "feedback": "Rätt – därför är den bäst att jämföra lån med."}, {"question": "Vad kan hända om en obetald skuld hamnar hos Kronofogden?", "options": ["Ingenting", "Du kan få en betalningsanmärkning", "Skulden försvinner", "Du får bostadsbidrag"], "correct_index": 1, "feedback": "Rätt – en betalningsanmärkning gör det svårare att till exempel hyra lägenhet."}, {"question": "Var kan du få gratis hjälp med skulder?", "options": ["Hos ett sms-lånebolag", "Hos budget- och skuldrådgivningen i kommunen", "Hos ett inkassobolag", "Ingenstans"], "correct_index": 1, "feedback": "Rätt – kommunens budget- och skuldrådgivning är gratis."}]}'::jsonb where id = 'barnbyar-5';
